css:
/* Award badges: a centred heading over rows of shield badges, seven across at 180px wide with 26px between.
   Each badge is three stars with a faded reflection, the award in two colours (<em> is the blue part, the
   year is the last line) and the maker's logo at the foot. */
[data-bz-node="ab-band"] > .bz-container { max-width: calc(min(90vw, 1440px) + 32px); }
[data-bz-section="award-badges"] .bz-block { padding-block: 0; }
[data-bz-section="award-badges"] h2 { margin: 0; text-align: center; font: 700 1.9rem / 1.2 var(--font-heading); color: #000; letter-spacing: 0; }
[data-bz-section="award-badges"] [data-bz-node="ab-row"] { margin: 54px auto 0; display: grid; grid-template-columns: repeat(7, 180px); justify-content: center; column-gap: 26px; row-gap: 57px; }
[data-bz-section="award-badges"] [data-bz-node="ab-row"] > .bz-col { grid-column: auto; position: relative; width: 180px; height: 260px; box-sizing: border-box; background: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 180 260'><path d='M2.5 2.500H177.500V217.500L90 258 2.500 217.500Z' fill='%23eaf7ff' stroke='%23c7e8f2' stroke-width='5'/><path d='M13 13H167V212L90 247 13 212Z' fill='none' stroke='%23d9eef8' stroke-width='1.500'/></svg>") center / 100% 100% no-repeat; }
[data-bz-section="award-badges"] [data-bz-node="ab-row"] > .bz-col::before, [data-bz-section="award-badges"] [data-bz-node="ab-row"] > .bz-col::after { content: ""; position: absolute; left: 30px; width: 120px; height: 40px; background: url("data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 120 40'><path fill='%230090e4' d='M14.5,7.8 L17.7,15.6 L26.1,16.2 L19.7,21.7 L21.7,29.9 L14.5,25.5 L7.3,29.9 L9.3,21.7 L2.9,16.2 L11.3,15.6ZM60.0,1.6 L64.3,12.0 L75.6,12.9 L67.0,20.3 L69.6,31.3 L60.0,25.4 L50.4,31.3 L53.0,20.3 L44.4,12.9 L55.7,12.0ZM105.5,7.8 L108.7,15.6 L117.1,16.2 L110.7,21.7 L112.7,29.9 L105.5,25.5 L98.3,29.9 L100.3,21.7 L93.9,16.2 L102.3,15.6Z'/></svg>") center / 100% 100% no-repeat; }
[data-bz-section="award-badges"] [data-bz-node="ab-row"] > .bz-col::before { top: 21px; }
[data-bz-section="award-badges"] [data-bz-node="ab-row"] > .bz-col::after { top: 41px; transform: scaleY(-1); opacity: 0.3; -webkit-mask-image: linear-gradient(to bottom, transparent 55%, #000 100%); mask-image: linear-gradient(to bottom, transparent 55%, #000 100%); }
[data-bz-section="award-badges"] [data-bz-node^="ab-label"] { position: absolute; left: 6px; right: 6px; top: 92px; height: 78px; display: flex; align-items: center; justify-content: center; }
[data-bz-section="award-badges"] [data-bz-node^="ab-label"] .bz-container { padding: 0; }
[data-bz-section="award-badges"] [data-bz-node^="ab-label"] .bz-text p { margin: 0; white-space: pre-line; text-align: center; font: 700 0.805rem / 1.25 var(--font-heading); color: #003550; max-width: none; }
[data-bz-section="award-badges"] [data-bz-node^="ab-label"] em { font-style: normal; color: var(--accent); }
[data-bz-section="award-badges"] [data-bz-node^="ab-logo"] { position: absolute; left: 0; right: 0; top: 176px; height: 44px; display: flex; align-items: center; justify-content: center; }
[data-bz-section="award-badges"] [data-bz-node^="ab-logo"] .bz-container { padding: 0; }
[data-bz-section="award-badges"] [data-bz-node^="ab-logo"] .bz-figure { margin: 0; display: flex; align-items: center; justify-content: center; }
[data-bz-section="award-badges"] [data-bz-node^="ab-logo"] img { display: block; width: auto; max-width: 70px; max-height: 44px; height: auto; border-radius: 0; }
[data-bz-section="award-badges"] .bz-photo--empty { display: none; }
@media (max-width: 1500px) { [data-bz-section="award-badges"] [data-bz-node="ab-row"] { grid-template-columns: repeat(6, 180px); } }
@media (max-width: 1300px) { [data-bz-section="award-badges"] [data-bz-node="ab-row"] { grid-template-columns: repeat(5, 180px); } }
@media (max-width: 1100px) { [data-bz-section="award-badges"] [data-bz-node="ab-row"] { grid-template-columns: repeat(4, 180px); } }
@media (max-width: 880px) { [data-bz-section="award-badges"] [data-bz-node="ab-row"] { grid-template-columns: repeat(3, 180px); } }
@media (max-width: 640px) { [data-bz-section="award-badges"] [data-bz-node="ab-row"] { grid-template-columns: repeat(2, 180px); column-gap: 16px; } [data-bz-section="award-badges"] h2 { font-size: 1.5rem; } }
@media (max-width: 420px) { [data-bz-section="award-badges"] [data-bz-node="ab-row"] { grid-template-columns: 180px; } }
